        if path == "/health":
            self.reply(HTTPStatus.OK, b"ok", "text/plain; charset=utf-8", head=head)
        elif path in ASSETS:
            name, content_type = ASSETS[path]
            self.reply(HTTPStatus.OK, (STATIC / name).read_bytes(), content_type, head=head)
