"""HTTP server: the page, its assets, and the JSON move API.

The server keeps no state between requests. The browser sends the whole
board with every move, the server checks it, plays the move (and the
computer's reply) and sends back the new board and where the game stands.
"""

import json
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from . import ai, game, signing

STATIC = Path(__file__).parent / "static"
# Only these files are served: a fixed map, so no path from a request ever
# reaches the file system.
ASSETS = {
    "/": ("index.html", "text/html; charset=utf-8"),
    "/static/style.css": ("style.css", "text/css; charset=utf-8"),
    "/static/app.js": ("app.js", "text/javascript; charset=utf-8"),
}
MODES = ("computer", "friend")
MAX_BODY = 1024


def handle_move(request: object) -> dict:
    """Answer one POST /api/move body. Raises IllegalMoveError on bad input."""
    if not isinstance(request, dict):
        raise game.IllegalMoveError("the body must be a JSON object")
    # A field sent as null counts as not sent.
    token = request.get("game")
    stolen = request.get("steal")
    # Without a token or a steal, exactly today's checks in today's order.
    judged = token is not None or stolen is not None
    if judged:
        board = game.check_cells(request.get("board"))
    else:
        board = game.validate(request.get("board"))
    mode = request.get("mode", "computer")
    if mode not in MODES:
        raise game.IllegalMoveError(f"mode must be one of: {', '.join(MODES)}")
    level = request.get("level", "hard")
    if mode == "computer":
        if level not in ai.LEVELS:
            raise game.IllegalMoveError(f"level must be one of: {', '.join(ai.LEVELS)}")
        if not judged and game.turn(board) != "X":
            raise game.IllegalMoveError("against the computer you play X")
    steals = signing.verify(token, board, level) if token is not None else 0
    if judged:
        if stolen is not None and request.get("cell") is not None:
            raise game.IllegalMoveError("send either cell or steal, not both")
        if stolen is not None and mode == "friend":
            raise game.IllegalMoveError("you can only steal from the computer")
        if stolen is not None and token is None:
            raise game.IllegalMoveError("a steal needs the game token from the last answer")
        board = game.validate(board, steals)
        if mode == "computer" and game.turn(board, steals) != "X":
            raise game.IllegalMoveError("against the computer you play X")
    # A token proves a chain of positions from an empty board: hand out a
    # first one only when this request starts a new game.
    chained = token is not None or not any(board)
    if stolen is not None:
        board = game.steal(board, stolen, steals)
        steals = 1
    else:
        board = game.play(board, request.get("cell"), steals)
    computer_move = None
    if mode == "computer" and game.outcome(board).status == "playing":
        computer_move = ai.choose_move(board, level, steals=steals)
        board = game.play(board, computer_move, steals)
    answer = describe(board, steals) | {"computer_move": computer_move}
    playing = answer["status"] == "playing"
    new_token = None
    if mode == "computer" and playing and chained:
        new_token = signing.sign(board, level, steals)
    can_steal = new_token is not None and steals == 0 and answer["turn"] == "X"
    return answer | {
        "game": new_token,
        "stealable": [i for i, cell in enumerate(board) if cell == "O"] if can_steal else [],
        "steal_used": steals == 1,
        "assisted": answer["winner"] == "X" and steals == 1,
    }


def describe(board: list[str], steals: int = 0) -> dict:
    result = game.outcome(board)
    return {
        "board": board,
        "status": result.status,
        "winner": result.winner,
        "line": list(result.line) if result.line else None,
        "turn": game.turn(board, steals) if result.status == "playing" else None,
    }


class Handler(BaseHTTPRequestHandler):
    server_version = "tictactoe"

    def do_GET(self) -> None:
        self.serve(head=False)

    def do_HEAD(self) -> None:
        self.serve(head=True)

    def do_POST(self) -> None:
        if self.path != "/api/move":
            self.reply_json(HTTPStatus.NOT_FOUND, {"error": "not found"})
            return
        length = self.headers.get("Content-Length", "")
        if not length.isdigit():
            self.reply_json(HTTPStatus.LENGTH_REQUIRED, {"error": "Content-Length required"})
            return
        if int(length) > MAX_BODY:
            self.reply_json(HTTPStatus.REQUEST_ENTITY_TOO_LARGE, {"error": "body too large"})
            return
        try:
            request = json.loads(self.rfile.read(int(length)) or b"null")
            answer = handle_move(request)
        except (ValueError, game.IllegalMoveError) as error:
            # json.JSONDecodeError and IllegalMoveError are both ValueErrors
            self.reply_json(HTTPStatus.BAD_REQUEST, {"error": str(error)})
            return
        self.reply_json(HTTPStatus.OK, answer)
        if request.get("steal") is not None:
            # Only a steal that was played gets here, so level and cell are
            # known-good values. Never log the token, the key or the board.
            self.log_message(
                "steal level=%s cell=%d status=%s assisted=%s",
                request["level"] if "level" in request else "hard",
                request["steal"],
                answer["status"],
                "true" if answer["assisted"] else "false",
            )

    def serve(self, *, head: bool) -> None:
        path = self.path.split("?", 1)[0]
        if path == "/health":
            self.reply(HTTPStatus.OK, b"ok", "text/plain; charset=utf-8", head=head)
        elif path in ASSETS:
            name, content_type = ASSETS[path]
            self.reply(HTTPStatus.OK, (STATIC / name).read_bytes(), content_type, head=head)
        elif path == "/api/move":
            self.send_response(HTTPStatus.METHOD_NOT_ALLOWED)
            self.send_header("Allow", "POST")
            self.send_header("Content-Length", "0")
            self.end_headers()
        else:
            self.reply(HTTPStatus.NOT_FOUND, b"not found", "text/plain; charset=utf-8", head=head)

    def reply_json(self, status: HTTPStatus, body: dict) -> None:
        self.reply(status, json.dumps(body).encode(), "application/json")

    def reply(
        self, status: HTTPStatus, body: bytes, content_type: str, *, head: bool = False
    ) -> None:
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-cache")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        if not head:
            self.wfile.write(body)


def make_server(host: str, port: int) -> ThreadingHTTPServer:
    return ThreadingHTTPServer((host, port), Handler)

